use client;

/**
 * PortfolioReadout component displays the current portfolio value with a smooth animation.
 */
const PortfolioReadout = () => {
  const shown = useCountUp(BLUEPRINT_SEED.portfolioValue);

  return (
    <section aria-label="Portfolio value" className="carbon-face checkered-sweep relative overflow-hidden rounded-lg border border-line p-5">
      <p className="num text-[10px] tracking-[0.2em] text-dim">PORTFOLIO VALUE</p>
      <p className="num mt-1 text-3xl font-bold text-amber">{formatINR(Math.round(shown))}</p>
      <p className="num mt-1 text-[10px] text-dim">current market value</p>
      <motion.div className="mt-4 h-[3px] rounded bg-amber/70"
        initial={{ scaleX: 0 }} animate={{ scaleX: 1 }}
        style={{ transformOrigin: "left" }}
        transition={{ duration: 1.1, ease: [0.16, 1, 0.3, 1] }} />
    </section>
  );
};

export default PortfolioReadout;
